operations.query:
mutation SupportArticleDelete($id: uuid!) {
  delete_assistant_articles_by_pk(id: $id) { id }
}

mutation SupportArticleInsert($object: assistant_articles_insert_input!) {
  insert_assistant_articles_one(object: $object) {
    id slug kind active published_at cover_image_url created_at updated_at is_published
    localizations(order_by: { locale: asc }) { article_id locale title summary body_md created_at updated_at }
  }
}

mutation SupportArticleLocalizationDelete($article_id: uuid!, $locale: String!) {
  delete_assistant_article_localizations_by_pk(article_id: $article_id, locale: $locale) { article_id }
}

mutation SupportArticleLocalizationUpsert($object: assistant_article_localizations_insert_input!) {
  insert_assistant_article_localizations_one(
    object: $object
    on_conflict: { constraint: article_localizations_pkey, update_columns: [title, summary, body_md] }
  ) { article_id locale }
}

mutation SupportArticleUpdate($id: uuid!, $set: assistant_articles_set_input!) {
  update_assistant_articles_by_pk(pk_columns: { id: $id }, _set: $set) {
    id slug kind active published_at cover_image_url created_at updated_at is_published
    localizations(order_by: { locale: asc }) { article_id locale title summary body_md created_at updated_at }
  }
}

query SupportArticles {
  assistant_articles(order_by: [{ published_at: desc_nulls_first }, { created_at: desc }]) {
    id slug kind active published_at cover_image_url created_at updated_at is_published
    localizations(order_by: { locale: asc }) { article_id locale title summary body_md created_at updated_at }
  }
}

mutation SupportCatalogDeactivateExercise($id: uuid!) {
      update_catalog_exercises_by_pk(pk_columns: { id: $id }, _set: { active: false }) { id }
    }

query SupportCatalogExerciseForSave($exo_id: Int!) {
      catalog_exercises(where: { exo_id: { _eq: $exo_id } }, limit: 1) {
        id exo_id taxonomy_status active display_name
        muscles_inherited muscles_custom_reason body_mass_coefficient default_pulley_ratio
        primary_muscle_group { code } movement_type { code } equipment { code }
        load_modality { code } logging_mode { code } target_muscle { code }
      }
    }

query SupportCatalogExerciseHistory($exo: String!, $prefix: String!) {
      catalog_change_log(
        where: {
          table_name: { _in: ["exercises", "exercise_localizations", "exercise_secondary_muscles"] }
          _or: [{ row_key: { _eq: $exo } }, { row_key: { _like: $prefix } }]
        }
        order_by: { id: desc }
        limit: 50
      ) { id changed_at actor table_name row_key op old_row new_row }
    }

query SupportCatalogFetchByExoId($exo_id: Int!) {
      catalog_exercises(where: { exo_id: { _eq: $exo_id } }, limit: 1) {
        id exo_id taxonomy_status active display_name
      }
    }

query SupportCatalogFindExerciseNames($where: catalog_exercise_localizations_bool_exp!) {
      catalog_exercise_localizations(where: $where) { locale display_name exercise { exo_id } }
    }

query SupportCatalogGuardContext($group: String!, $movement: String!, $target: String!) {
      group: catalog_muscle_groups(where: { code: { _eq: $group } }, limit: 1) { code kind }
      pair: catalog_muscle_group_movement_types(
        where: { muscle_group: { code: { _eq: $group } }, movement_type: { code: { _eq: $movement } } }
        limit: 1
      ) {
        target_muscle { code }
        target_profiles { target_muscle { code } }
      }
      target: catalog_muscles(where: { code: { _eq: $target } }, limit: 1) { code home_muscle_group { code } }
    }

mutation SupportCatalogInsertExercise($o: catalog_exercises_insert_input!) {
      insert_catalog_exercises_one(object: $o) { id exo_id display_name taxonomy_status }
    }

mutation SupportCatalogInsertExerciseGivingPairMuscles(
        $o: catalog_exercises_insert_input!
        $g: uuid!
        $m: uuid!
      ) {
        insert_catalog_exercises_one(object: $o) { id exo_id display_name taxonomy_status }
        update_catalog_exercises(
          where: {
            primary_muscle_group_id: { _eq: $g }
            movement_type_id: { _eq: $m }
            active: { _eq: true }
            muscles_inherited: { _eq: false }
            muscles_custom_reason: { _is_null: true }
          }
          _set: { muscles_inherited: true }
        ) { affected_rows }
      }

mutation SupportCatalogUpdateExercise(
            $id: uuid!
            $set: catalog_exercises_set_input!
            $localizations: [catalog_exercise_localizations_insert_input!]!
          ) {
            update_catalog_exercises_by_pk(pk_columns: { id: $id }, _set: $set) { id exo_id taxonomy_status }
            insert_catalog_exercise_localizations(
              objects: $localizations
              on_conflict: {
                constraint: exercise_localizations_exercise_id_locale_key
                update_columns: [display_name, description]
              }
            ) { affected_rows }
          }

mutation SupportCatalogUpdateExerciseInheritAtEnd(
          $id: uuid!
          $set: catalog_exercises_set_input!
          $localizations: [catalog_exercise_localizations_insert_input!]!
          $secondary: [catalog_exercise_secondary_muscles_insert_input!]!
        ) {
          update_catalog_exercises_by_pk(pk_columns: { id: $id }, _set: $set) { id exo_id taxonomy_status }
          delete_catalog_exercise_secondary_muscles(where: { exercise_id: { _eq: $id } }) { affected_rows }
          insert_catalog_exercise_secondary_muscles(objects: $secondary) { affected_rows }
          insert_catalog_exercise_localizations(
            objects: $localizations
            on_conflict: {
              constraint: exercise_localizations_exercise_id_locale_key
              update_columns: [display_name, description]
            }
          ) { affected_rows }
          inherit: update_catalog_exercises_by_pk(pk_columns: { id: $id }, _set: { muscles_inherited: true }) { id }
        }

mutation SupportCatalogUpdateExerciseSecondary(
            $id: uuid!
            $set: catalog_exercises_set_input!
            $localizations: [catalog_exercise_localizations_insert_input!]!
            $secondary: [catalog_exercise_secondary_muscles_insert_input!]!
          ) {
            update_catalog_exercises_by_pk(pk_columns: { id: $id }, _set: $set) { id exo_id taxonomy_status }
            delete_catalog_exercise_secondary_muscles(where: { exercise_id: { _eq: $id } }) { affected_rows }
            insert_catalog_exercise_secondary_muscles(objects: $secondary) { affected_rows }
            insert_catalog_exercise_localizations(
              objects: $localizations
              on_conflict: {
                constraint: exercise_localizations_exercise_id_locale_key
                update_columns: [display_name, description]
              }
            ) { affected_rows }
          }

