query SupportImagesGetExerciseSummary($exoId: Int!) {
      catalog_exercises(where: { exo_id: { _eq: $exoId } }, limit: 1) {

  id
  exo_id
  display_name
  active
  primary_muscle_group { id name }
  equipment { id code name description }
  support_equipment { id code name description }
  position { code name }
  grip { code name description }
  variation { code name }
  localizations { locale display_name description }

      }
    }

query SupportImagesGetImageExercise($exoId: Int!, $styleId: uuid!) {
      images_exercise_options_by_pk(exo_id: $exoId) { two_frames }
      catalog_exercises(where: { exo_id: { _eq: $exoId } }, limit: 1) {

  id
  exo_id
  display_name
  active
  primary_muscle_group { id name }
  equipment { id code name description }
  support_equipment { id code name description }
  position { code name }
  grip { code name description }
  variation { code name }
  localizations { locale display_name description }

      }
