query SupportUserCoach($id: uuid!, $tier: String!) {
          periods: assistant_usage_periods(
            where: { user_id: { _eq: $id } }
            order_by: { period_start: desc }
            limit: 24
          ) {
            user_id
            period_start
            period_end
            input_tokens
            output_tokens
            embed_tokens
            reserved_tokens
          }
          policy: assistant_tier_policies_by_pk(tier_code: $tier) {
            monthly_token_limit
            weekly_token_limit
            hourly_burst_limit
          }
          quota: assistant_user_quota(args: { p_user_id: $id }) {
            llm_enabled
            period_limit period_used period_remaining
            week_limit week_used week_remaining
            hour_limit hour_used hour_remaining
            remaining scope resets_at
          }
        }

query SupportUserCoachTier($id: uuid!) {
          profiles_by_pk(id: $id) { effective_subscription_tier }
        }

query SupportUserCustom($id: uuid!) {
          customExercises: workout_custom_exercises(
            where: { user_id: { _eq: $id } }
            order_by: { updated_at: desc }
            limit: 50
          ) {
            id
            display_name
            active
            inserted_at
            updated_at
          }
        }

query SupportUserLookup($id: uuid!) {
      users(where: { id: { _eq: $id } }, limit: 1) {
        id
        email
        emailVerified
        disabled
        createdAt
        lastSeen
        defaultRole
        roles { role }
      }
      profiles(where: { id: { _eq: $id } }, limit: 1) {
        id
        username
        display_name
        date_of_birth
        gender
        height_cm
        weight_kg
        sessions_per_week
        hypertrophy_level
        strength_level
        endurance_level
        avatar_url
        effective_subscription_tier
        inserted_at
        updated_at
        entitlement {
          tier_code
          source
          expires_at
          play_purchase_token
          play_state
          play_product_id
          play_base_plan_id
          play_expiry_time
          play_auto_renewing
          play_in_free_trial
          period_started_at
          updated_at
        }
      }
      subscription_tiers {
        code
        display_name
        templates_limit
        history_months
        routines_enabled
        support_enabled
      }
      grants: billing_manual_grants(
        where: { user_id: { _eq: $id } }
        order_by: { inserted_at: desc }
        limit: 20
      ) {
        id
        tier_code
        ends_at
        reason
        granted_by
        revoked_at
        inserted_at
      }
      workout_sessions_aggregate(
        where: { user_id: { _eq: $id }, ended_at: { _is_null: false } }
      ) {
        aggregate { count }
      }
      open_session: workout_sessions(
        where: { user_id: { _eq: $id }, ended_at: { _is_null: true } }
        limit: 1
      ) {
        id
        name
        started_at
      }
      workout_templates_aggregate(where: { user_id: { _eq: $id } }) {
        aggregate { count }
      }
      routines: workout_routines(where: { user_id: { _eq: $id } }, limit: 500) {
        id
      }
      customExercises: workout_custom_exercises(where: { user_id: { _eq: $id } }, limit: 500) {
        id
      }
    }

query SupportUserRoutines($id: uuid!) {
          routines: workout_routines(
            where: { user_id: { _eq: $id } }
            order_by: { updated_at: desc }
            limit: 50
          ) {
            id
            name
            is_active
            last_performed_at
            updated_at
            steps { id }
          }
        }

query SupportUserSearch($pattern: citext!, $patternText: String!, $limit: Int!) {
      byEmail: users(
        where: { email: { _ilike: $pattern } }
        order_by: { email: asc }
        limit: $limit
      ) {
        id
        email
        emailVerified
        disabled
        defaultRole
        roles { role }
      }
      byProfile: profiles(
        where: {
          _or: [
            { username: { _ilike: $pattern } }
            { display_name: { _ilike: $patternText } }
          ]
        }
        order_by: { username: asc_nulls_last }
        limit: $limit
      ) {
        id
        username
        display_name
        effective_subscription_tier
        user {
          id
          email
          emailVerified
          disabled
          defaultRole
          roles { role }
        }
      }
    }

query SupportUserSessions($id: uuid!) {
          open_session: workout_sessions(
            where: { user_id: { _eq: $id }, ended_at: { _is_null: true } }
            limit: 1
          ) {
            id
            name
            started_at
          }
          sessions: v_session_list_summary(
            where: { user_id: { _eq: $id } }
            order_by: { started_at: desc }
            limit: 50
          ) {
            session_id
            name
            started_at
            ended_at
            session_tonnage_kg
            total_sets
            total_reps
            exercise_count
            main_muscle_groups
            template_id
          }
        }

query SupportUserTemplates($id: uuid!) {
          templates: workout_templates(
            where: { user_id: { _eq: $id } }
            order_by: { updated_at: desc }
            limit: 50
          ) {
            id
            name
            sort_order
            inserted_at
            updated_at
            exercises { id }
          }
        }

query SupportXcatLibraryAdmin {
      catalog_exercises(where: { active: { _eq: true } }, order_by: { exo_id: asc }) {
        id
        exo_id
        display_name
        localizations(order_by: { locale: asc }) { locale display_name description }
        taxonomy_status
        taxonomy_notes
        primary_muscle_group { code name }
        target_muscle { code name }
        muscles_inherited
        resolved_muscles(order_by: { sort_order: asc }) { role source muscle { code name } }
        movement_type { code name }
        equipment { code name }
        support_equipment { code name }
        variation { code name }
        position { code name }
        grip { code name }
        load_modality { code name }
        logging_mode { code name }
        body_mass_coefficient
        default_pulley_ratio
        secondary_muscles(order_by: { sort_order: asc }) { muscle { code name } }
      }
      catalog_muscle_groups(where: { active: { _eq: true } }, order_by: { sort_order: asc }) {
        id code name
      }
      catalog_muscles(where: { active: { _eq: true } }, order_by: { code: asc }) {
        id code name
      }
      catalog_movement_types(where: { active: { _eq: true } }, order_by: { sort_order: asc, code: asc }) {
        id code name
      }
      catalog_equipment(where: { active: { _eq: true } }, order_by: { sort_order: asc, code: asc }) {
        id code name
        localizations(order_by: { locale: asc }) { locale display_name }
      }
      catalog_support_equipment(where: { active: { _eq: true } }, order_by: { sort_order: asc, code: asc }) {
        id code name
        localizations(order_by: { locale: asc }) { locale display_name }
      }
      catalog_load_modalities(where: { active: { _eq: true } }, order_by: { sort_order: asc, code: asc }) {
        id code name
      }
      catalog_logging_modes(where: { active: { _eq: true } }, order_by: { sort_order: asc, code: asc }) {
        id code name
      }
    }
